#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
# A batch of single validation runs (host must be in split mode). Each line of the plan: <label> [ENV=VALUE ...].
# Usage: scripts/night_runs.sh <log_dir> <<PLAN ... PLAN  → appends "<label> <campaign_dir>" to <log_dir>/night_runs.txt. Values with spaces: VAR='a b' (plain single quotes).
set -u
cd "$(dirname "$0")/.."
LD=${1:?log dir}; mkdir -p "$LD"
# NIGHT_RUNS_NO_SPLIT=1: functional validation runs (no timing claims) may run with the host in off mode
[ "${NIGHT_RUNS_NO_SPLIT:-0}" = 1 ] || sudo -n /usr/local/sbin/fish-host-perf-mode status 2>/dev/null | grep -q "smt             : off" || { echo "ABORT: host not in split mode" | tee -a "$LD/night_runs.txt"; exit 2; }
# Thermal validity (2026-10-05): a run during which the package throttles is not a timing measurement (daytime
# campaign: 31 500 throttle events, application CPU 5.6 instead of 3.95 cores, chain latency x4). Each run starts
# only when the package is below NIGHT_RUNS_COOL_C (default 56 C; idle is ~52 C; waits up to NIGHT_RUNS_COOL_MAX_S = 600 s) and
# the throttle events during the run are logged ("thr=+N"; N > 0 → discard the run for timing purposes).
thr() { cat /sys/devices/system/cpu/cpu0/thermal_throttle/package_throttle_count 2>/dev/null || echo 0; }
ptemp() { local z; for z in /sys/class/thermal/thermal_zone*; do case "$(cat "$z/type" 2>/dev/null)" in x86_pkg_temp|TCPU) echo $(( $(cat "$z/temp") / 1000 )); return;; esac; done; echo 0; }
cooldown() { local t0=$SECONDS; while [ "$(ptemp)" -ge "${NIGHT_RUNS_COOL_C:-56}" ] && [ $((SECONDS - t0)) -lt "${NIGHT_RUNS_COOL_MAX_S:-600}" ]; do sleep 10; done; }
# Desktop validity (2026-10-05): in split mode the desktop lives on CPUs 18-19. Heavy browsing there (1.3-2.0 busy
# cores instead of the 0.4-0.7 of the night campaign) coincided with traced runs at 5.1-5.6 application cores instead
# of 3.95 and a chain latency of 450-600 ms instead of 155 ms — on the old image as well. Each run starts only when
# the desktop CPUs are below NIGHT_RUNS_DESK_MAX busy cores (default 0.8, sampled over 10 s, waits up to 600 s) and
# the mean over the run is logged ("desk=X"; above the limit → discard the run for timing purposes).
deskj() { LC_ALL=C awk '$1=="cpu18"||$1=="cpu19"{s+=$2+$3+$4+$7+$8} END{print s+0}' /proc/stat; }
deskwait() { local t0=$SECONDS a b; while :; do a=$(deskj); sleep 10; b=$(deskj); LC_ALL=C awk -v d=$((b - a)) -v m="${NIGHT_RUNS_DESK_MAX:-0.8}" 'BEGIN{exit !(d/1000 < m)}' && break; [ $((SECONDS - t0)) -ge 600 ] && break; done; }
while read -r LABEL REST; do
  [ -z "$LABEL" ] && continue
  cooldown; [ "${NIGHT_RUNS_NO_SPLIT:-0}" = 1 ] || deskwait; THR0=$(thr); TEMP0=$(ptemp); DJ0=$(deskj); DT0=$SECONDS
  # REST may contain quoted values with spaces: eval the assignment list into an env invocation
  eval "env FISH_TRACE_TIER=max FISH_APP_CPUS=0,2,4,6,8,10 FISH_OBS_CPUS=12-17 FISH_CDDS_XML=1 FISH_KERNEL_SCHED=1 FISH_PER_INSTANCE=true \
       FISH_EVENT_COUNT=0 REPS=1 MODES=nsys IMG=autoware-dev-trt-a1000-fishwait19:latest RATE=0.5 $REST \
       bash scripts/autoware_runs/run_overhead_modes.sh" > "$LD/run_$LABEL.log" 2>&1 < /dev/null
  D=$(grep -o 'campaign → [^ ]*' "$LD/run_$LABEL.log" | head -1 | cut -d' ' -f3)
  echo "$LABEL $D rc=$? $(date +%T) thr=+$(( $(thr) - THR0 )) temp0=${TEMP0}C temp1=$(ptemp)C desk=$(LC_ALL=C awk -v d=$(( $(deskj) - DJ0 )) -v t=$((SECONDS - DT0)) 'BEGIN{printf "%.2f", (t > 0 ? d / 100 / t : 0)}')" >> "$LD/night_runs.txt"
done
echo "BATCH DONE $(date +%T)" >> "$LD/night_runs.txt"
